// Animates Nhimbaloth Encounter/presenece
// Adds tentacles and an overlay over the screen for the duration
// Requires Sequencer & can use JB2A Patreon
const duration = 10; // In seconds
const fadeInDuration = 1; // In seconds
const fadeOutDuration = 1; // In seconds
const sfx = "modules/pf2e-abomination-vaults/assets/audio/motifs/whispering-reeds/010H.ogg"; // BG sound to play
const volume = 1; // Volume Level 0 - 1 (1 = 100%)

await game.abomVaultAddons.animations.nhimbalothPresence({duration, fadeInDuration, fadeOutDuration, sfx, volume});
